// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(sender != address(0));
        vm.assume(depositAmount >= 1 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(sender);

        vm.prank(sender);
        // Collect may revert if MinSum condition not satisfied; we handle that
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));

        if (success) {
            uint256 balanceAfter = c.balances(sender);
            assertTrue(balanceAfter == balanceBefore - withdrawAmount, "balance difference incorrect");
        } else {
            // If revert, balance unchanged
            uint256 balanceAfter = c.balances(sender);
            assertTrue(balanceAfter == balanceBefore, "balance changed on revert");
        }
    }
}

