pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, address other, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable values
        depositAmount = bound(depositAmount, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, 100 ether);

        // Initialize the contract
        c.Initialized();

        // Give sender some ETH
        vm.deal(sender, 100 ether);

        // Deposit from sender
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Get total balances before Collect
        uint256 balanceBefore = c.balances(sender) + c.balances(other);

        // Try to collect (may revert)
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Get total balances after Collect
        uint256 balanceAfter = c.balances(sender) + c.balances(other);

        // The sum of all balances must not change regardless of success or failure
        assertTrue(balanceBefore == balanceAfter || (success && balanceAfter <= balanceBefore));
    }
}

