pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 minSum, uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(caller != other && caller != address(0) && other != address(0));
        vm.assume(depositAmt > 0 && depositAmt <= type(uint256).max / 2);
        vm.assume(collectAmt <= depositAmt);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Record other's balance before Collect
        uint256 otherBalanceBefore = c.balances(other);

        // Try Collect from caller
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // Assert: other's balance unchanged
        assertTrue(c.balances(other) == otherBalanceBefore);
    }
}

