pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 minSum, uint256 am) public {
        // bound values to avoid overflow/revert
        vm.assume(caller != address(0));
        initialBalance = bound(initialBalance, 0, 1e30);
        minSum = bound(minSum, 0, 1e30);
        am = bound(am, 0, 1e30);
        vm.assume(initialBalance >= minSum && initialBalance >= am); // precondition for Collect to not revert

        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        vm.prank(caller);
        c.SetMinSum(minSum);
        c.Initialized();

        uint256 callerBalBefore = c.balances(caller);
        uint256 contractBalBefore = address(c).balance;

        vm.prank(caller);
        c.Collect(am);

        uint256 callerBalAfter = c.balances(caller);
        uint256 contractBalAfter = address(c).balance;

        assertTrue(callerBalAfter == callerBalBefore - am && contractBalAfter == contractBalBefore - am, "Balance invariant violated");
    }
}

