// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Bound deposit to be reasonable (e.g., 0 to 100 ether) and collectAmount to be <= balance
        vm.assume(depositAmount <= 100 ether);
        vm.assume(collectAmount <= depositAmount);
        // Ensure caller is not the zero address and contract has enough ETH to call
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Initialize the contract (one-time setup)
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect with enough balance
        vm.prank(caller);
        c.Collect(collectAmount);

        // Record balance after Collect
        uint256 balanceAfter = c.balances(caller);

        // GENERAL RULE: In the reference, balance decreases (or stays same if collectAmount=0)
        // In the buggy version, balance never decreases (stays same), so after Collect balanceAfter >= balanceBefore
        // To distinguish, we check that balanceAfter > balanceBefore (strict increase) which is only true in buggy version
        // Since reference always decreases or stays same (never increases), this assertion fails on reference
        // Wait, we need reference to PASS and bug to FAIL. So we assert the OPPOSITE: that balanceAfter <= balanceBefore
        // Actually, re-reading: rule must hold for reference and break for bug.
        // Reference: balanceAfter = balanceBefore - collectAmount (non-negative, so <= balanceBefore)
        // Bug: balanceAfter = balanceBefore (unchanged) => equal, so <= holds too.
        // Need a property that reference satisfies but bug violates. 
        // Bug: after Collect, balanceAfter = balanceBefore. Reference: balanceAfter = balanceBefore - collectAmount.
        // So property: balanceAfter <= balanceBefore - 1 (if collectAmount > 0) doesn't hold for bug.
        // Let's use: if collectAmount > 0, then balanceAfter != balanceBefore (reference) vs bug (balanceAfter == balanceBefore).
        // But we need a general rule with only public getters.
        // Let's do: balanceBefore - balanceAfter == collectAmount (reference) vs bug (balanceBefore - balanceAfter == 0).
        // For reference: always true if Collect succeeds (balance >= MinSum and balance >= collectAmount). We must ensure that.

        // Ensure Collect actually executes the logic (MinSum met, balance >= collect)
        vm.assume(balanceBefore >= c.MinSum());
        vm.assume(balanceBefore >= collectAmount);

        // Now the property: balanceBefore - balanceAfter equals collectAmount
        // Reference: yes (balance decreased by exactly collectAmount)
        // Bug: balanceBefore - balanceAfter = 0, so fails when collectAmount > 0
        vm.assume(collectAmount > 0);

        assertTrue(balanceBefore - balanceAfter == collectAmount, "Balance difference should equal collected amount");
    }
}

