pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address who, uint256 am, uint256 toSend) public {
        // Ensure non-zero address and sufficient initial balance
        vm.assume(who != address(0));
        vm.assume(am < 100 ether);
        vm.assume(toSend < 100 ether);

        // Set MinSum to 1 ether (default) or user-defined
        c.SetMinSum(1 ether);
        c.Initialized();

        // Pre-fund the caller and contract
        vm.deal(who, toSend);
        vm.deal(address(c), 10 ether);

        // Deposit some funds for the caller
        vm.prank(who);
        c.Deposit{value: toSend}();

        // Record state before Collect
        uint256 callerBalanceBefore = c.balances(who);
        uint256 contractBalanceBefore = address(c).balance;
        uint256 sumBefore = callerBalanceBefore + contractBalanceBefore;

        // Call Collect
        vm.prank(who);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // Record state after Collect (only if it succeeded)
        if (success) {
            uint256 callerBalanceAfter = c.balances(who);
            uint256 contractBalanceAfter = address(c).balance;
            uint256 sumAfter = callerBalanceAfter + contractBalanceAfter;
            // The sum must not increase (bug makes caller's balance stay same, but contract loses ether)
            assertTrue(sumAfter <= sumBefore, "Sum increased after Collect");
        }
    }
}

