contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount >= 1 ether && depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount <= depositAmount);

        // Initialize the contract
        c.Initialized();

        // Fund the caller and deposit into contract
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Get initial Log length
        uint256 initLogLength = c.Log.History.length; // Access Log via public getter pattern? Actually Log is a contract instance, need to read length via LogFile's public History array
        // But we cannot directly call LogFile since it's not in scope. Instead, we check the revert boolean of Collect.

        // Record caller's balance before Collect
        uint256 callerBalanceBefore = address(caller).balance;

        // Call Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Rule: If Collect succeeded (no revert) and the caller's balance increased by exactly collectAmount, then the call actually went through the successful path.
        // Actually we can only observe the revert boolean. The buggy version reverts on success, so:
        // For the reference: Collect should succeed if balances[caller] >= MinSum && balances[caller] >= collectAmount
        // For the bug: It reverts when the external call succeeds.
        // So the rule: If the caller's balance after the call increased by collectAmount (meaning the ether was sent), then the original contract must not revert. But the buggy contract reverts in that case.
        // Better: check that if Collect reverts, then the caller's balance did NOT increase by collectAmount (i.e., no transfer happened).

        // Read caller's balance after
        uint256 callerBalanceAfter = address(caller).balance;
        bool balanceIncreased = (callerBalanceAfter == callerBalanceBefore + collectAmount);

        // The rule: success == balanceIncreased (i.e., Collect succeeds exactly when the transfer happened)
        assertTrue(balanceIncreased == success, "balance increased iff Collect succeeds");
    }
}

